func (q *Queries) TakedownPublishedPost(ctx context.Context, arg TakedownPublishedPostParams) (Post, error) {
	row := q.db.QueryRow(ctx, takedownPublishedPost, arg.Reason, arg.ID, arg.CommunityID)
	var i Post
	err := row.Scan(
		&i.ID,
		&i.CommunityID,
		&i.AuthorID,
		&i.RequiredTierLevel,
		&i.Title,
		&i.Status,
		&i.CurrentVersionID,
		&i.PublishedVersionID,
		&i.RemovedReason,
		&i.RestoredFromVersionID,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const withdrawSubmission = `-- name: WithdrawSubmission :one
UPDATE posts
SET status = 'draft', updated_at = now()
WHERE id = $1 AND community_id = $2 AND status = 'pending'
RETURNING id, community_id, author_id, required_tier_level, title, status, current_version_id, published_version_id, removed_reason, restored_from_version_id, created_at, updated_at
`

type WithdrawSubmissionParams struct {
	ID          int64 `json:"id"`
	CommunityID int64 `json:"community_id"`
}

// Author pulls a pending submission back to draft.
func (q *Queries) WithdrawSubmission(ctx context.Context, arg WithdrawSubmissionParams) (Post, error) {
	row := q.db.QueryRow(ctx, withdrawSubmission, arg.ID, arg.CommunityID)
	var i Post
	err := row.Scan(
		&i.ID,
		&i.CommunityID,
		&i.AuthorID,
		&i.RequiredTierLevel,
		&i.Title,
		&i.Status,
		&i.CurrentVersionID,
		&i.PublishedVersionID,
		&i.RemovedReason,
		&i.RestoredFromVersionID,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
